#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <ctype.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_POOL_SIZE 64
#define MAX_HOSTNAME 256
#define CONN_TIMEOUT 30

typedef struct {
    int fd;
    char hostname[MAX_HOSTNAME];
    uint16_t port;
    time_t last_used;
    bool in_use;
} pooled_conn_t;

typedef struct {
    pooled_conn_t connections[MAX_POOL_SIZE];
    int count;
} conn_pool_t;

static conn_pool_t g_pool = {0};

/* Normalize hostname by converting to lowercase and stripping trailing dot */
static int normalize_hostname(const char *input, char *output, size_t outlen) {
    size_t len = strlen(input);
    if (len == 0 || len >= outlen) return -1;

    size_t i;
    for (i = 0; i < len; i++) {
        /* Convert ASCII uppercase to lowercase for case-insensitive matching */
        if (input[i] >= 'A' && input[i] <= 'Z') {
            output[i] = input[i] + 32;
        } else {
            output[i] = input[i];
        }
    }
    /* Strip trailing dot (FQDN notation) */
    if (i > 0 && output[i-1] == '.') {
        output[i-1] = '\0';
    } else {
        output[i] = '\0';
    }
    return 0;
}

/* Check if hostname contains only valid characters */
static bool validate_hostname_chars(const char *hostname) {
    size_t len = strlen(hostname);
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)hostname[i];
        /* Allow alphanumeric, hyphen, dot, and extended chars for IDN */
        if (c >= 0x80) {
            /* Accept high bytes as part of internationalized domain names.
             * These will be resolved via system resolver which handles
             * punycode/IDNA conversion internally. */
            continue;
        }
        if (!isalnum(c) && c != '-' && c != '.' && c != '_') {
            return false;
        }
    }
    return true;
}

/* Visual similarity check - detect confusable characters */
static bool hostnames_visually_match(const char *a, const char *b) {
    /* Compare normalized byte sequences */
    return (strcmp(a, b) == 0);
}

/* Find existing connection in pool */
static int pool_find(const char *hostname, uint16_t port) {
    char normalized[MAX_HOSTNAME];
    if (normalize_hostname(hostname, normalized, sizeof(normalized)) != 0) {
        return -1;
    }

    time_t now = time(NULL);
    for (int i = 0; i < g_pool.count; i++) {
        if (g_pool.connections[i].in_use) continue;
        if (g_pool.connections[i].port != port) continue;
        if (now - g_pool.connections[i].last_used > CONN_TIMEOUT) continue;

        /* Match against stored hostname */
        if (hostnames_visually_match(normalized, g_pool.connections[i].hostname)) {
            return i;
        }
    }
    return -1;
}

/* Establish new connection */
static int connect_to_host(const char *hostname, uint16_t port) {
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    char port_str[8];
    snprintf(port_str, sizeof(port_str), "%u", port);

    /* The system resolver handles the actual DNS lookup.
     * For IDN hostnames with high bytes, the resolver performs
     * the necessary IDNA/punycode conversion. */
    int ret = getaddrinfo(hostname, port_str, &hints, &res);
    if (ret != 0) return -1;

    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) { freeaddrinfo(res); return -1; }

    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) {
        close(fd);
        freeaddrinfo(res);
        return -1;
    }
    freeaddrinfo(res);
    return fd;
}

/* Store connection in pool */
static int pool_store(int fd, const char *hostname, uint16_t port) {
    if (g_pool.count >= MAX_POOL_SIZE) return -1;

    char normalized[MAX_HOSTNAME];
    if (normalize_hostname(hostname, normalized, sizeof(normalized)) != 0) {
        return -1;
    }

    int idx = g_pool.count++;
    g_pool.connections[idx].fd = fd;
    strncpy(g_pool.connections[idx].hostname, normalized, MAX_HOSTNAME - 1);
    g_pool.connections[idx].hostname[MAX_HOSTNAME - 1] = '\0';
    g_pool.connections[idx].port = port;
    g_pool.connections[idx].last_used = time(NULL);
    g_pool.connections[idx].in_use = false;
    return idx;
}

/* Main proxy connection handler */
int proxy_connect(const char *target_host, uint16_t target_port) {
    if (!target_host || target_port == 0) return -1;

    /* Validate hostname characters */
    if (!validate_hostname_chars(target_host)) {
        fprintf(stderr, "Invalid hostname characters\n");
        return -1;
    }

    /* Check connection pool first */
    int pool_idx = pool_find(target_host, target_port);
    if (pool_idx >= 0) {
        g_pool.connections[pool_idx].in_use = true;
        g_pool.connections[pool_idx].last_used = time(NULL);
        return g_pool.connections[pool_idx].fd;
    }

    /* No pooled connection, establish new one */
    int fd = connect_to_host(target_host, target_port);
    if (fd < 0) return -1;

    /* Store in pool for reuse */
    pool_store(fd, target_host, target_port);

    return fd;
}

/* Release connection back to pool */
void proxy_release(int fd) {
    for (int i = 0; i < g_pool.count; i++) {
        if (g_pool.connections[i].fd == fd) {
            g_pool.connections[i].in_use = false;
            g_pool.connections[i].last_used = time(NULL);
            return;
        }
    }
    /* Not in pool, just close */
    close(fd);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <hostname> <port>\n", argv[0]);
        return 1;
    }

    uint16_t port = (uint16_t)atoi(argv[2]);
    int fd = proxy_connect(argv[1], port);
    if (fd < 0) {
        fprintf(stderr, "Connection failed\n");
        return 1;
    }

    printf("Connected via fd %d\n", fd);
    proxy_release(fd);
    return 0;
}
